;(() => {
  if (window.__WINGS_STRIP_DUCK__) return;
  window.__WINGS_STRIP_DUCK__ = true;
  function strip(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll(".font-semibold > span[aria-hidden='true'], .font-semibold > span[role='img']").forEach((el) => {
      if (el.querySelector("img[alt='WINGS']")) return;
      el.remove();
    });
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    for (const n of nodes) {
      if (n.nodeValue && n.nodeValue.includes("쿠팡 상품")) {
        n.nodeValue = n.nodeValue.replace("쿠팡 상품", "WINGS 소싱");
      }
    }
  }
  function scan() {
    document.querySelectorAll("[data-wxt-shadow-root]").forEach((host) => strip(host.shadowRoot));
  }
  scan();
  setInterval(scan, 800);
})();
